/* features: 19 float; out_probabilities: 5 float veya NULL.
   Dönüş: en olası sınıfın indeksi. */
static int emergency_classifier_predict(const float* features, float* out_probabilities) {
    float votes[5] = {0};
    emergency_classifier_tree_0(features, votes);
    emergency_classifier_tree_1(features, votes);
    emergency_classifier_tree_2(features, votes);
    emergency_classifier_tree_3(features, votes);
    emergency_classifier_tree_4(features, votes);
    emergency_classifier_tree_5(features, votes);
    emergency_classifier_tree_6(features, votes);
    emergency_classifier_tree_7(features, votes);
    emergency_classifier_tree_8(features, votes);
    emergency_classifier_tree_9(features, votes);
    emergency_classifier_tree_10(features, votes);
    emergency_classifier_tree_11(features, votes);
    emergency_classifier_tree_12(features, votes);
    emergency_classifier_tree_13(features, votes);
    emergency_classifier_tree_14(features, votes);
    emergency_classifier_tree_15(features, votes);
    emergency_classifier_tree_16(features, votes);
    emergency_classifier_tree_17(features, votes);
    emergency_classifier_tree_18(features, votes);
    emergency_classifier_tree_19(features, votes);
    emergency_classifier_tree_20(features, votes);
    emergency_classifier_tree_21(features, votes);
    emergency_classifier_tree_22(features, votes);
    emergency_classifier_tree_23(features, votes);
    emergency_classifier_tree_24(features, votes);

    int best_class = 0;
    float max_prob = -1.0f;
    for (int c = 0; c < 5; c++) {
        float p = votes[c] / (float)25;
        if (out_probabilities) out_probabilities[c] = p;
        if (p > max_prob) {
            max_prob = p;
            best_class = c;
        }
    }
    return best_class;
}

